import * as THREE from 'three/webgpu';
import { texture as textureNode } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Load and configure texture
  const texture = ctx.textureLoader.load('/prism-mock/home/nodes/feature-card.png');
  texture.colorSpace = THREE.SRGBColorSpace;

  // Create plane geometry (512:320 aspect ratio = 1.6:1)
  const width = 1.6;
  const height = 1;
  const geometry = new THREE.PlaneGeometry(width, height);

  // Create material with TSL nodes
  const material = new THREE.MeshBasicNodeMaterial({
    colorNode: textureNode(texture),
    transparent: true,
    side: THREE.DoubleSide,
  });

  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // Apply scene placement from config
  if (config.scenePosition) {
    group.position.fromArray(config.scenePosition);
  }
  if (config.rotation) {
    group.rotation.fromArray(config.rotation);
  }
  if (config.scale) {
    group.scale.fromArray(config.scale);
  }

  // Store base Y position for animations
  const baseY = group.position.y;
  let hoverTimeline = null;

  // Define event handlers
  const handlers = {
    hover: () => {
      if (hoverTimeline) hoverTimeline.kill();
      hoverTimeline = gsap.to(group.position, {
        y: baseY + 0.15,
        duration: 0.7,
        ease: 'power3.out',
      });
    },
    unhover: () => {
      if (hoverTimeline) hoverTimeline.kill();
      hoverTimeline = gsap.to(group.position, {
        y: baseY,
        duration: 0.5,
        ease: 'power2.out',
      });
    },
    click: () => {
      // Emit hub-journal.select event
      if (ctx.emit) {
        ctx.emit('hub-journal.select', { nodeId: config.nodeId });
      }

      // Press-down animation
      gsap.to(group.scale, {
        x: 0.97,
        y: 0.97,
        duration: 0.12,
        ease: 'back.out',
        yoyo: true,
        repeat: 1,
      });
    },
  };

  group.userData.handlers = handlers;

  // Apply cinematic primitive: parallax-scroll
  if (ctx.primitives && ctx.primitives['parallax-scroll']) {
    ctx.primitives['parallax-scroll'](group, { intensity: 0.25 });
  }

  // Cleanup function
  group.userData.cleanup = () => {
    if (hoverTimeline) hoverTimeline.kill();
    geometry.dispose();
    material.dispose();
    texture.dispose();
  };

  return group;
}
